                for j in range(i + 1, N):
                    if A[j] == smallest_permutation[i] and A[i] == smallest_permutation[j]:
                        # Swap A[i] and A[j]
                        A[i], A[j] = A[j], A[i]
                        found = True
                        break
                if found:
                    break

        # If we couldn't find two swaps, try one more swap
        if not found:
            for i in range(N):
                if A[i] != smallest_permutation[i]:
                    for j in range(i + 1, N):
